import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for KeyedObjects2D.removeObject
 */
public class KeyedObjects2D_removeObject_TriageGen2Test {

    private KeyedObjects2D dataset;
    private final Comparable row1 = "Row1";
    private final Comparable row2 = "Row2";
    private final Comparable col1 = "Col1";
    private final Comparable col2 = "Col2";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    /**
     * Test removing an object where the row still contains other objects.
     * This covers the branch where allNull (row check) is false.
     */
    @Test
    public void testRemoveObject_RowNotEmpty() {
        dataset.addObject("Data1", row1, col1);
        dataset.addObject("Data2", row1, col2);

        dataset.removeObject(row1, col1);

        assertNull("Object at (row1, col1) should be null", dataset.getObject(row1, col1));
        assertEquals("Row1 should still exist", "Data2", dataset.getObject(row1, col2));
        assertEquals("Row count should remain 1", 1, dataset.getRowCount());
    }










}

