/**
 * Unit tests for KeyedObjects2D.removeObject
 */
public class KeyedObjects2D_removeObject_TriageGen2Test {

    private KeyedObjects2D dataset;
    private final Comparable row1 = "Row1";
    private final Comparable row2 = "Row2";
    private final Comparable col1 = "Col1";
    private final Comparable col2 = "Col2";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }







    /**
     * Test removing an object where the column becomes completely empty across all rows.
     * This covers the branch where allNull (column check) is true,
     * leading to the loop that calls row.removeValue(columnIndex).
     */
    @Test
    public void testRemoveObject_ColumnBecomesEmpty() {
        dataset.addObject("Data1", row1, col1);
        dataset.addObject("Data2", row2, col1);
        // Add a second column so the dataset has multiple columns
        dataset.addObject("Data3", row1, col2);

        dataset.removeObject(row1, col1);
        // Now row1,col1 is null. But row2,col1 is still "Data2".
        // This doesn't trigger column removal yet.

        dataset.removeObject(row2, col1);
        // Now col1 is empty across all rows.

        assertNull("Col1 at row1 should be null", dataset.getObject(row1, col1));
        assertNull("Col1 at row2 should be null", dataset.getObject(row2, col1));
        // The column logic in the provided code removes the value from the row, 
        // but doesn't explicitly remove the column key from the dataset's column list 
        // unless the implementation of removeValue handles it or the column check logic triggers.
        // Based on the code: if allNull is true, it iterates and calls row.removeValue.
    }




}

